actions.script:
File dir = new File(ec.factory.runtimePath, 'ownerData')
if (!dir.isDirectory() && !dir.mkdirs() && !dir.isDirectory()) {
    throw new IllegalStateException('SQLite import temporary directory unavailable')
}
File temp = File.createTempFile('nasqo-sqlite-import-', '.back', dir)
try {
    file.inputStream.withCloseable { InputStream input ->
        temp.outputStream.withCloseable { OutputStream output -> input.transferTo(output) }
    }
    def util = ec.resource.script('component://growerp/service/NasqoSqliteImportUtil.groovy', null)
    preview = util.preview(temp)
} finally {
    temp.delete()
}
